<script setup lang="ts">
import {ref,computed} from 'vue';import Button from 'primevue/button';import Dialog from 'primevue/dialog';import Select from 'primevue/select';import Textarea from 'primevue/textarea';import DataTable from 'primevue/datatable';import Column from 'primevue/column';import {useToast} from 'primevue/usetoast';import {api,currentUser} from '../lib/api';import {useQuery} from '../composables/useQuery';import {date,initials,type Data} from '../lib/types';import QueryState from '../components/QueryState.vue';import StatusBadge from '../components/StatusBadge.vue';
const transitions:Record<string,{label:string;value:string}[]>={OPEN:[{label:'Tiếp nhận xử lý',value:'IN_PROGRESS'}],IN_PROGRESS:[{label:'Đã giải quyết',value:'RESOLVED'},{label:'Chuyển cấp',value:'ESCALATED'}],ESCALATED:[{label:'Tiếp tục xử lý',value:'IN_PROGRESS'},{label:'Đã giải quyết',value:'RESOLVED'}],RESOLVED:[{label:'Mở lại',value:'OPEN'},{label:'Đóng yêu cầu',value:'CLOSED'}]};
const status=ref<string|null>(null),selected=ref<Data>(),show=ref(false),message=ref(''),target=ref('IN_PROGRESS'),reason=ref(''),busy=ref(false),toast=useToast();const {data,loading,error,refresh}=useQuery(()=>api('/admin/support/tickets'+(status.value?'?status='+status.value:'')),15000);const safety=useQuery(()=>api('/admin/safety-incidents'),15000);
const allowedTransitions=computed(()=>transitions[selected.value?.ticket.status]??[]);
let detailRevision=0;
async function open(t:Data){const revision=++detailRevision;try{const result=await api('/support/tickets/'+t.id);if(revision!==detailRevision)return;if(selected.value?.ticket.id!==t.id)message.value='';selected.value=result;show.value=true;target.value=(transitions[result.ticket.status]??[])[0]?.value??'';reason.value='';}catch(e){if(revision===detailRevision)toast.add({severity:'error',summary:(e as Error).message});}}
async function reply(){if(!selected.value||selected.value.ticket.status==='CLOSED'||!message.value.trim()||message.value.length>5000||busy.value)return;busy.value=true;try{await api('/support/tickets/'+selected.value.ticket.id+'/messages',{method:'POST',body:{body:message.value.trim()}});message.value='';await open(selected.value.ticket);}catch(e){toast.add({severity:'error',summary:(e as Error).message});}finally{busy.value=false;}}
async function transition(){if(!selected.value)return;busy.value=true;try{await api('/admin/support/tickets/'+selected.value.ticket.id+'/transitions',{method:'POST',body:{expectedVersion:selected.value.ticket.version,status:target.value,reasonCode:reason.value}});await open(selected.value.ticket);await refresh();toast.add({severity:'success',summary:'Đã cập nhật yêu cầu',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
async function acknowledge(id:string){try{await api('/admin/safety-incidents/'+id+'/acknowledge',{method:'POST'});await safety.refresh();toast.add({severity:'success',summary:'Đã xác nhận tiếp nhận cảnh báo',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message});}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">LUÔN Ở ĐÂY ĐỂ HỖ TRỢ</div><h1>Trung tâm hỗ trợ<span class="green-text">.</span></h1><p>Tiếp nhận kịp thời, xử lý có trách nhiệm.</p></div><span class="date-pill"><i class="pi pi-headphones"></i>{{data?.items.length??0}} yêu cầu</span></div><section v-if="safety.data.value?.items.length" class="panel safety-panel"><div class="panel-header"><h2><i class="pi pi-exclamation-triangle"></i> Cảnh báo an toàn</h2></div><div v-for="incident in safety.data.value.items" :key="incident.id" class="zone-row"><i class="pi pi-shield form-error"></i><div><strong>Cảnh báo SOS</strong><p>{{date(incident.createdAt)}} · {{incident.status==='ACKNOWLEDGED'?'Đã tiếp nhận':'Chưa được tiếp nhận'}}</p></div><Button v-if="incident.status!=='ACKNOWLEDGED' && currentUser?.role==='SupportAgent'" label="Xác nhận tiếp nhận" severity="danger" @click="acknowledge(incident.id)"/></div></section><QueryState :loading="safety.loading.value" :error="safety.error.value" @retry="safety.refresh"/><section class="panel"><div class="filter-bar"><Select v-model="status" aria-label="Lọc trạng thái yêu cầu" :options="[{label:'Tất cả yêu cầu',value:null},{label:'Chờ tiếp nhận',value:'OPEN'},{label:'Đang xử lý',value:'IN_PROGRESS'},{label:'Đã giải quyết',value:'RESOLVED'},{label:'Chuyển cấp',value:'ESCALATED'},{label:'Đã đóng',value:'CLOSED'}]" option-label="label" option-value="value" @change="refresh"/><span class="filter-count">Ưu tiên an toàn và các khoản thu tranh chấp</span></div><QueryState :loading="loading" :error="error" @retry="refresh"/><DataTable v-if="data" :value="data.items" row-hover paginator :rows="10" class="grap-table" @row-click="open($event.data)"><template #empty><div class="table-empty">Chưa có yêu cầu phù hợp.</div></template><Column header="YÊU CẦU"><template #body="{data:d}"><strong>{{d.subject}}</strong><small class="cell-muted">{{date(d.createdAt)}}</small></template></Column><Column header="NGƯỜI GỬI"><template #body="{data:d}"><div class="person-cell"><span class="avatar small lavender">{{initials(d.requesterName)}}</span>{{d.requesterName}}</div></template></Column><Column header="ƯU TIÊN"><template #body="{data:d}"><span class="priority" :class="d.priority.toLowerCase()">{{({URGENT:'Khẩn cấp',HIGH:'Cao',NORMAL:'Thông thường'} as Data)[d.priority]}}</span></template></Column><Column header="TRẠNG THÁI"><template #body="{data:d}"><StatusBadge :status="d.status==='IN_PROGRESS'?'IN_PROGRESS_TICKET':d.status"/></template></Column><Column><template #body="{data:d}"><Button icon="pi pi-arrow-up-right" text aria-label="Xem yêu cầu" @click.stop="open(d)"/></template></Column></DataTable></section><Dialog v-model:visible="show" modal header="Xử lý yêu cầu hỗ trợ" :style="{width:'660px'}"><template v-if="selected"><div class="detail-title"><h2>{{selected.ticket.subject}}</h2><StatusBadge :status="selected.ticket.status==='IN_PROGRESS'?'IN_PROGRESS_TICKET':selected.ticket.status"/></div><div class="message-thread"><div v-for="m in selected.messages" :key="m.id" class="message-bubble" :class="{own:m.authorId===currentUser?.id}"><p>{{m.body}}</p><small>{{m.authorId===currentUser?.id?'Bạn':'Người gửi'}} · {{date(m.createdAt)}}</small></div></div><template v-if="selected.ticket.status!=='CLOSED'"><label>Phản hồi<Textarea v-model="message" class="full-width" rows="3" placeholder="Nhập nội dung phản hồi…" :maxlength="5000"/></label><Button label="Gửi phản hồi" icon="pi pi-send" :disabled="!message.trim()||message.length>5000" :loading="busy" @click="reply"/></template><div v-else class="info-box"><i class="pi pi-lock"></i><p>Yêu cầu đã đóng. Hội thoại được giữ lại để tra cứu.</p></div><div v-if="currentUser?.role==='SupportAgent' && selected.ticket.status!=='CLOSED'" class="ticket-transition"><h3>Cập nhật xử lý</h3><Select v-model="target" :options="allowedTransitions" option-label="label" option-value="value" class="full-width"/><label>Lý do cập nhật<Textarea v-model="reason" rows="2" class="full-width"/></label><Button label="Lưu trạng thái" outlined :disabled="reason.trim().length<3" :loading="busy" @click="transition"/></div></template></Dialog></template>
